import{_ as o,C as a,o as i,c as d,a2 as t,b as c,w as s,a as h,E as n,a3 as p}from"./chunks/framework.CHjbm2Wd.js";const _=JSON.parse('{"title":"Simulink → flight code","description":"Model referencing, data dictionaries, Embedded Coder, and integrating generated code.","frontmatter":{"title":"Simulink → flight code","description":"Model referencing, data dictionaries, Embedded Coder, and integrating generated code."},"headers":[],"relativePath":"flight/simulink-pipeline.md","filePath":"flight/simulink-pipeline.md","lastUpdated":1792993690000}'),m={name:"flight/simulink-pipeline.md"};function g(u,e,b,k,f,y){const r=a("Mermaid"),l=a("Quiz");return i(),d("div",null,[e[1]||(e[1]=t('<h1 id="simulink-→-flight-code" tabindex="-1">Simulink → flight code <a class="header-anchor" href="#simulink-→-flight-code" aria-label="Permalink to &quot;Simulink → flight code&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">Why this matters</p><p>Many GNC organizations design in Simulink and generate C for the flight processor. The handoff is where model assumptions meet compiler flags, sample times, data types, and a handwritten application. If you can explain that pipeline, you can integrate with a GNC team instead of just reading their diagrams.</p></div><h2 id="learning-objectives" tabindex="-1">Learning objectives <a class="header-anchor" href="#learning-objectives" aria-label="Permalink to &quot;Learning objectives&quot;">​</a></h2><ul><li>Structure a model for code generation: plant, controller, harness, data dictionary.</li><li>Choose fixed-step, discrete sample times and data types.</li><li>Use model referencing and buses to define interfaces.</li><li>Generate code with Embedded Coder and integrate the generated API.</li><li>Run MIL/SIL/PIL/back-to-back tests.</li><li>Diagnose the common model-to-code mismatches.</li></ul><h2 id="the-model-based-design-flow" tabindex="-1">The model-based design flow <a class="header-anchor" href="#the-model-based-design-flow" aria-label="Permalink to &quot;The model-based design flow&quot;">​</a></h2>',5)),(i(),c(p,null,{default:s(()=>[n(r,{id:"mermaid-46",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20R%5BRequirements%5D%20--%3E%20M%5BModel%5D%0A%20%20%20%20M%20--%3E%20MIL%5BMIL%20test%5D%0A%20%20%20%20MIL%20--%3E%20C%5BCode%20generation%5D%0A%20%20%20%20C%20--%3E%20SIL%5BSIL%20test%5D%0A%20%20%20%20SIL%20--%3E%20PIL%5BPIL%20test%5D%0A%20%20%20%20PIL%20--%3E%20HIL%5BHIL%20test%5D%0A%20%20%20%20HIL%20--%3E%20F%5BFlight%5D%0A%20%20%20%20M%20--%3E%20V%5BModel%20Advisor%20%2F%20coverage%5D%0A%20%20%20%20V%20--%3E%20C%0A"})]),fallback:s(()=>[...e[0]||(e[0]=[h(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t(`<p>The model is not the flight code. It is a specification that a generator translates. The translation has assumptions, and those assumptions are your integration risk.</p><h2 id="structure-the-model-for-generation" tabindex="-1">Structure the model for generation <a class="header-anchor" href="#structure-the-model-for-generation" aria-label="Permalink to &quot;Structure the model for generation&quot;">​</a></h2><p>A workable split:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>controller.slx          # the part that becomes flight code</span></span>
<span class="line"><span>plant.slx               # simulation-only</span></span>
<span class="line"><span>sensor_model.slx        # simulation-only</span></span>
<span class="line"><span>test_harness.slx        # MIL/SIL/PIL harness</span></span>
<span class="line"><span>data/</span></span>
<span class="line"><span>  controller.sldd       # data dictionary</span></span>
<span class="line"><span>  params.m              # initialization</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>Use <strong>model references</strong> for the controller so it can be generated and tested independently. Keep simulation-only blocks (scopes, plant dynamics, noise) out of the generated subsystem. Use <strong>variant subsystems</strong> for test vs flight configurations, but verify which variant was built.</p><h2 id="data-dictionary-and-buses" tabindex="-1">Data dictionary and buses <a class="header-anchor" href="#data-dictionary-and-buses" aria-label="Permalink to &quot;Data dictionary and buses&quot;">​</a></h2><p>Interfaces should be explicit:</p><ul><li>define a <code>Bus</code> for <code>NavState</code>, <code>GuidanceCmd</code>, <code>ActuatorCmd</code>,</li><li>set units and ranges in the data dictionary,</li><li>define every parameter with a storage class,</li><li>avoid magic numbers in blocks.</li></ul><p>A bus is the model equivalent of a message schema. If the bus changes, every consumer changes. That is a feature.</p><h2 id="sample-times-and-rates" tabindex="-1">Sample times and rates <a class="header-anchor" href="#sample-times-and-rates" aria-label="Permalink to &quot;Sample times and rates&quot;">​</a></h2><p>For generated flight code:</p><ul><li>use a <strong>fixed-step discrete</strong> solver,</li><li>set the controller sample time explicitly (e.g., <code>0.01</code> s),</li><li>make rate transitions explicit with rate-transition blocks,</li><li>avoid algebraic loops,</li><li>verify that every rate is an integer multiple of the base rate,</li><li>document the task that calls each rate.</li></ul><p>A model that runs at a variable step in simulation may generate code that assumes a fixed step. That mismatch is a classic integration bug.</p><h2 id="data-types-and-fixed-point" tabindex="-1">Data types and fixed point <a class="header-anchor" href="#data-types-and-fixed-point" aria-label="Permalink to &quot;Data types and fixed point&quot;">​</a></h2><p>Flight code often uses <code>single</code> or fixed-point types for memory and determinism. If you use floating point:</p><ul><li>confirm the target has an FPU and the compiler flags are correct,</li><li>check NaN/Inf behavior,</li><li>compare host and target results,</li><li>avoid <code>double</code> in a memory-constrained loop unless needed.</li></ul><p>If you use fixed point:</p><ul><li>choose scaling and word length deliberately,</li><li>check overflow and quantization,</li><li>test at the extremes,</li><li>document the scaling in the data dictionary.</li></ul><h2 id="embedded-coder" tabindex="-1">Embedded Coder <a class="header-anchor" href="#embedded-coder" aria-label="Permalink to &quot;Embedded Coder&quot;">​</a></h2><p>Typical settings:</p><ul><li>system target file: <code>ert.tlc</code> (or your program’s target),</li><li>language: C or C++,</li><li>generate a reusable function interface,</li><li>static allocation,</li><li>no dynamic memory,</li><li>code style and naming per the program,</li><li>comments and traceability,</li><li>calibration/measurement support (A2L/ASAP2) if the program uses it,</li><li>report generation.</li></ul><p>Generated API (names vary):</p><div class="language-c vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">void</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> controller_initialize</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">void</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">void</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> controller_step</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">void</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">void</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> controller_terminate</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">void</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">extern</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Controller_U controller_U;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   // inputs</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">extern</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Controller_Y controller_Y;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   // outputs</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>A handwritten wrapper maps the flight software’s messages to <code>controller_U</code>, calls <code>controller_step()</code> at the right rate, and copies <code>controller_Y</code> to the actuator command. The wrapper is flight code too; it needs tests.</p><h2 id="integration-checklist" tabindex="-1">Integration checklist <a class="header-anchor" href="#integration-checklist" aria-label="Permalink to &quot;Integration checklist&quot;">​</a></h2><ul><li>[ ] Generated code compiles with the target compiler and flags.</li><li>[ ] No dynamic allocation in the generated code.</li><li>[ ] All states are initialized before the first step.</li><li>[ ] The step function is called at the model’s sample time.</li><li>[ ] Inputs are validated and range-checked.</li><li>[ ] Outputs are saturated and checked.</li><li>[ ] Units and frames match the interface.</li><li>[ ] The generated code is versioned with the model.</li><li>[ ] The target build is tested, not just the host build.</li><li>[ ] The model and code are traceable to requirements.</li></ul><h2 id="verification" tabindex="-1">Verification <a class="header-anchor" href="#verification" aria-label="Permalink to &quot;Verification&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Test</th><th>What it checks</th></tr></thead><tbody><tr><td><strong>Model Advisor</strong></td><td>Modeling standards and code-generation readiness</td></tr><tr><td><strong>MIL</strong></td><td>Algorithm behavior in the model</td></tr><tr><td><strong>SIL</strong></td><td>Generated code behavior on the host</td></tr><tr><td><strong>PIL</strong></td><td>Generated code on the target processor</td></tr><tr><td><strong>Back-to-back</strong></td><td>Model vs code equivalence</td></tr><tr><td><strong>Coverage</strong></td><td>Model and code coverage</td></tr><tr><td><strong>Requirements link</strong></td><td>Traceability to requirements</td></tr></tbody></table><p>Back-to-back testing is essential. A model that passes MIL and code that compiles is not proof that the generated code implements the same behavior.</p><h2 id="common-failures" tabindex="-1">Common failures <a class="header-anchor" href="#common-failures" aria-label="Permalink to &quot;Common failures&quot;">​</a></h2><ol><li><strong>Sample-time mismatch.</strong> The model assumes 10 ms; the scheduler calls it at 20 ms.</li><li><strong>Algebraic loop.</strong> The generated code has a direct feedthrough path that the target cannot execute in one step.</li><li><strong>Data-type mismatch.</strong> <code>double</code> in the model, <code>single</code> on the target; results diverge.</li><li><strong>State initialization.</strong> The generated code starts from zero, but the model started from a trimmed operating point.</li><li><strong>Frame/unit mismatch.</strong> The model’s attitude is body-to-inertial; the interface expects inertial-to-body.</li><li><strong>Hidden state.</strong> A block with internal state is not reset between runs.</li><li><strong>Optimizer differences.</strong> Floating-point reassociation changes a limit case.</li><li><strong>Handwritten wrapper bugs.</strong> The generated code is fine; the mapping is wrong.</li><li><strong>Version skew.</strong> The model, data dictionary, and generated code are from different commits.</li><li><strong>Target library differences.</strong> <code>sin</code>, <code>cos</code>, or <code>sqrt</code> behave differently on the target.</li></ol><h2 id="practice" tabindex="-1">Practice <a class="header-anchor" href="#practice" aria-label="Permalink to &quot;Practice&quot;">​</a></h2><ol><li>Build a discrete controller model with a bus input and output. Generate C.</li><li>Write a handwritten wrapper that calls <code>initialize</code> and <code>step</code> at 100 Hz.</li><li>Run a back-to-back test: same inputs to the model and the generated code; compare outputs.</li><li>Change the sample time to 20 Hz and observe the closed-loop degradation.</li><li>Introduce a unit mismatch in the wrapper and write a test that catches it.</li></ol>`,33)),n(l,{question:"The model passes MIL and the generated code compiles. What is the most important missing check?",options:"A prettier block diagram|Back-to-back/SIL comparison of the model and generated code, plus target timing|A larger scope|More comments",answer:"1",explanation:"Compilation is not equivalence. Back-to-back or SIL/PIL testing checks that the generated code behaves like the model, and target timing checks that it runs at the required rate."}),e[3]||(e[3]=t('<h2 id="resources" tabindex="-1">Resources <a class="header-anchor" href="#resources" aria-label="Permalink to &quot;Resources&quot;">​</a></h2><ul><li><a href="https://www.mathworks.com/products/embedded-coder.html" target="_blank" rel="noreferrer">MathWorks Embedded Coder</a> — code generation and targets.</li><li><a href="https://www.mathworks.com/products/simulink-test.html" target="_blank" rel="noreferrer">Simulink Test</a> — MIL/SIL/PIL and baselines.</li><li><a href="https://www.mathworks.com/help/simulink/ug/consult-the-model-advisor.html" target="_blank" rel="noreferrer">Model Advisor</a> — modeling standards.</li><li><a href="https://www.rtca.org/" target="_blank" rel="noreferrer">DO-331</a> — model-based development and verification guidance (airborne analogue).</li></ul><p>Next: <a href="./cfs.html">NASA cFS</a>.</p>',3))])}const w=o(m,[["render",g]]);export{_ as __pageData,w as default};
